// FreeLang Runtime Caching Layer
// Hub-Spoke cache architecture for function dispatch optimization

use std::collections::VecDeque;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};

/// Hub Cache: Central LRU cache for 16 most-used functions
/// Size: 16 entries × 64-byte aligned = 1KB per core
#[repr(C, align(64))]
pub struct HubCacheEntry {
    func_id: u64,
    arg_pattern: u64,
    result: u64,
    timestamp: u64,
}

pub struct HubCache {
    entries: VecDeque<HubCacheEntry>,
    capacity: usize,
    hits: AtomicU64,
    misses: AtomicU64,
}

impl HubCache {
    pub fn new(capacity: usize) -> Self {
        HubCache {
            entries: VecDeque::with_capacity(capacity),
            capacity,
            hits: AtomicU64::new(0),
            misses: AtomicU64::new(0),
        }
    }

    /// O(1) lookup for hot functions
    pub fn lookup(&self, func_id: u64, arg_pattern: u64) -> Option<u64> {
        for entry in self.entries.iter() {
            if entry.func_id == func_id && entry.arg_pattern == arg_pattern {
                self.hits.fetch_add(1, Ordering::Relaxed);
                return Some(entry.result);
            }
        }
        self.misses.fetch_add(1, Ordering::Relaxed);
        None
    }

    /// Insert with automatic eviction (LRU)
    pub fn insert(&mut self, func_id: u64, arg_pattern: u64, result: u64) {
        if self.entries.len() >= self.capacity {
            self.entries.pop_front(); // Evict oldest
        }

        let timestamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos() as u64;

        self.entries.push_back(HubCacheEntry {
            func_id,
            arg_pattern,
            result,
            timestamp,
        });
    }

    pub fn hit_rate(&self) -> f64 {
        let hits = self.hits.load(Ordering::Relaxed);
        let misses = self.misses.load(Ordering::Relaxed);
        let total = hits + misses;
        if total == 0 { 0.0 } else { hits as f64 / total as f64 }
    }

    pub fn stats(&self) -> (u64, u64) {
        (
            self.hits.load(Ordering::Relaxed),
            self.misses.load(Ordering::Relaxed),
        )
    }

    pub fn clear(&mut self) {
        self.entries.clear();
    }
}

/// Spoke Cache: Per-callsite cache for warm functions
pub struct SpokeCache {
    func_id: u64,
    entries: Vec<(u64, u64)>, // (arg_pattern, result)
    max_entries: usize,
    hits: AtomicU64,
    misses: AtomicU64,
}

impl SpokeCache {
    pub fn new(func_id: u64, max_entries: usize) -> Self {
        SpokeCache {
            func_id,
            entries: Vec::with_capacity(max_entries),
            max_entries,
            hits: AtomicU64::new(0),
            misses: AtomicU64::new(0),
        }
    }

    pub fn lookup(&self, arg_pattern: u64) -> Option<u64> {
        for (pattern, result) in &self.entries {
            if *pattern == arg_pattern {
                self.hits.fetch_add(1, Ordering::Relaxed);
                return Some(*result);
            }
        }
        self.misses.fetch_add(1, Ordering::Relaxed);
        None
    }

    pub fn insert(&mut self, arg_pattern: u64, result: u64) {
        if self.entries.len() >= self.max_entries {
            // Remove oldest (first) entry
            self.entries.remove(0);
        }
        self.entries.push((arg_pattern, result));
    }

    pub fn hit_rate(&self) -> f64 {
        let hits = self.hits.load(Ordering::Relaxed);
        let misses = self.misses.load(Ordering::Relaxed);
        let total = hits + misses;
        if total == 0 { 0.0 } else { hits as f64 / total as f64 }
    }

    pub fn clear(&mut self) {
        self.entries.clear();
    }
}

/// Hub-Spoke Cache Manager: Orchestrates hub + spokes
pub struct HubSpokeCacheManager {
    hub: Arc<Mutex<HubCache>>,
    spokes: Arc<Mutex<Vec<Arc<Mutex<SpokeCache>>>>>,
    total_requests: AtomicU64,
    total_hits: AtomicU64,
}

impl HubSpokeCacheManager {
    pub fn new(hub_capacity: usize, num_spokes: usize, spoke_capacity: usize) -> Self {
        let mut spokes = Vec::with_capacity(num_spokes);
        for i in 0..num_spokes {
            spokes.push(Arc::new(Mutex::new(SpokeCache::new(
                i as u64,
                spoke_capacity,
            ))));
        }

        HubSpokeCacheManager {
            hub: Arc::new(Mutex::new(HubCache::new(hub_capacity))),
            spokes: Arc::new(Mutex::new(spokes)),
            total_requests: AtomicU64::new(0),
            total_hits: AtomicU64::new(0),
        }
    }

    /// Two-level lookup: Hub first, then Spoke
    pub fn lookup(&self, func_id: u64, arg_pattern: u64) -> Option<u64> {
        self.total_requests.fetch_add(1, Ordering::Relaxed);

        // Check Hub
        if let Ok(hub) = self.hub.lock() {
            if let Some(result) = hub.lookup(func_id, arg_pattern) {
                self.total_hits.fetch_add(1, Ordering::Relaxed);
                return Some(result);
            }
        }

        // Check Spoke (spoke index = func_id % num_spokes)
        if let Ok(spokes) = self.spokes.lock() {
            let spoke_idx = (func_id as usize) % spokes.len();
            if let Ok(mut spoke) = spokes[spoke_idx].lock() {
                if let Some(result) = spoke.lookup(arg_pattern) {
                    self.total_hits.fetch_add(1, Ordering::Relaxed);
                    return Some(result);
                }
            }
        }

        None
    }

    /// Insert to both Hub and Spoke
    pub fn insert(&self, func_id: u64, arg_pattern: u64, result: u64) {
        // Insert to Hub
        if let Ok(mut hub) = self.hub.lock() {
            hub.insert(func_id, arg_pattern, result);
        }

        // Insert to Spoke
        if let Ok(spokes) = self.spokes.lock() {
            let spoke_idx = (func_id as usize) % spokes.len();
            if let Ok(mut spoke) = spokes[spoke_idx].lock() {
                spoke.insert(arg_pattern, result);
            }
        }
    }

    pub fn overall_hit_rate(&self) -> f64 {
        let hits = self.total_hits.load(Ordering::Relaxed);
        let requests = self.total_requests.load(Ordering::Relaxed);
        if requests == 0 { 0.0 } else { hits as f64 / requests as f64 }
    }

    pub fn stats(&self) -> (u64, u64, f64) {
        let hits = self.total_hits.load(Ordering::Relaxed);
        let requests = self.total_requests.load(Ordering::Relaxed);
        let rate = if requests == 0 { 0.0 } else { hits as f64 / requests as f64 };
        (hits, requests, rate)
    }

    pub fn clear(&self) {
        if let Ok(mut hub) = self.hub.lock() {
            hub.clear();
        }
        if let Ok(spokes) = self.spokes.lock() {
            for spoke in spokes.iter() {
                if let Ok(mut s) = spoke.lock() {
                    s.clear();
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_hub_cache_insertion() {
        let mut hub = HubCache::new(16);
        hub.insert(1, 100, 42);
        assert_eq!(hub.lookup(1, 100), Some(42));
    }

    #[test]
    fn test_hub_cache_lru_eviction() {
        let mut hub = HubCache::new(2);
        hub.insert(1, 100, 42);
        hub.insert(2, 200, 84);
        hub.insert(3, 300, 126); // Should evict (1, 100, 42)
        assert_eq!(hub.lookup(1, 100), None);
        assert_eq!(hub.lookup(2, 200), Some(84));
    }

    #[test]
    fn test_hub_cache_hit_rate() {
        let mut hub = HubCache::new(16);
        hub.insert(1, 100, 42);
        hub.lookup(1, 100); // hit
        hub.lookup(1, 200); // miss
        let rate = hub.hit_rate();
        assert!(rate > 0.4 && rate < 0.6); // ~50%
    }

    #[test]
    fn test_spoke_cache_insertion() {
        let mut spoke = SpokeCache::new(1, 8);
        spoke.insert(100, 42);
        assert_eq!(spoke.lookup(100), Some(42));
    }

    #[test]
    fn test_spoke_cache_multiple_entries() {
        let mut spoke = SpokeCache::new(1, 8);
        spoke.insert(100, 42);
        spoke.insert(200, 84);
        spoke.insert(300, 126);
        assert_eq!(spoke.lookup(100), Some(42));
        assert_eq!(spoke.lookup(200), Some(84));
        assert_eq!(spoke.lookup(300), Some(126));
    }

    #[test]
    fn test_hub_spoke_manager_hub_lookup() {
        let mgr = HubSpokeCacheManager::new(16, 4, 8);
        mgr.insert(1, 100, 42);
        assert_eq!(mgr.lookup(1, 100), Some(42));
    }

    #[test]
    fn test_hub_spoke_manager_spoke_lookup() {
        let mgr = HubSpokeCacheManager::new(2, 4, 8);
        // Insert enough to fill hub and force spoke usage
        mgr.insert(10, 100, 1000);
        mgr.insert(11, 200, 2000);
        mgr.insert(12, 300, 3000);
        mgr.insert(13, 400, 4000); // Hub is now full

        // This should use spoke cache
        assert_eq!(mgr.lookup(13, 400), Some(4000));
    }

    #[test]
    fn test_hub_spoke_manager_stats() {
        let mgr = HubSpokeCacheManager::new(16, 4, 8);
        mgr.insert(1, 100, 42);
        mgr.lookup(1, 100); // hit
        mgr.lookup(1, 200); // miss

        let (hits, requests, rate) = mgr.stats();
        assert_eq!(requests, 2);
        assert_eq!(hits, 1);
        assert!(rate > 0.4 && rate < 0.6);
    }

    #[test]
    fn test_hub_spoke_manager_clear() {
        let mgr = HubSpokeCacheManager::new(16, 4, 8);
        mgr.insert(1, 100, 42);
        mgr.clear();
        assert_eq!(mgr.lookup(1, 100), None);
    }

    #[test]
    fn test_hub_spoke_manager_multi_func() {
        let mgr = HubSpokeCacheManager::new(16, 4, 8);
        mgr.insert(1, 100, 42);
        mgr.insert(2, 100, 84);
        mgr.insert(3, 100, 126);

        assert_eq!(mgr.lookup(1, 100), Some(42));
        assert_eq!(mgr.lookup(2, 100), Some(84));
        assert_eq!(mgr.lookup(3, 100), Some(126));
    }

    #[test]
    fn test_hub_spoke_manager_high_load() {
        let mgr = HubSpokeCacheManager::new(16, 4, 8);

        // Simulate 1000 requests with ~80% hit rate pattern
        for i in 0..1000 {
            let func_id = (i / 200) as u64; // 5 hot functions
            let arg_pattern = (i % 100) as u64;

            if i % 5 == 0 {
                mgr.insert(func_id, arg_pattern, i as u64);
            } else {
                mgr.lookup(func_id, arg_pattern);
            }
        }

        let (_, total, rate) = mgr.stats();
        assert!(total > 0);
        assert!(rate > 0.5); // Should have decent hit rate
    }

    #[test]
    fn test_concurrent_access_safety() {
        use std::thread;

        let mgr = Arc::new(HubSpokeCacheManager::new(16, 4, 8));
        let mut handles = vec![];

        for t in 0..4 {
            let mgr_clone = Arc::clone(&mgr);
            let handle = thread::spawn(move || {
                for i in 0..100 {
                    let func_id = (t * 100 + i) as u64;
                    mgr_clone.insert(func_id, i as u64, (func_id * i as u64));
                    mgr_clone.lookup(func_id, i as u64);
                }
            });
            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        let (_, total, _) = mgr.stats();
        assert!(total > 0);
    }
}

