// Shared Memory & Token Caching for Parallel Compilation
// Enables 4 worker threads to share compilation artifacts

use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::sync::atomic::{AtomicU64, Ordering};

/// Token: Represents a lexical token in source code
#[derive(Debug, Clone, Eq, PartialEq, Hash)]
pub struct Token {
    pub id: u64,
    pub token_type: u8,  // 0=keyword, 1=identifier, 2=literal, etc
    pub value: String,
    pub line: u32,
    pub column: u32,
}

impl Token {
    pub fn new(id: u64, token_type: u8, value: String, line: u32, column: u32) -> Self {
        Token {
            id,
            token_type,
            value,
            line,
            column,
        }
    }
}

/// TokenCache: Shared cache for frequently tokenized strings
/// Reduces re-tokenization overhead
pub struct TokenCache {
    pub tokens: Vec<Token>,
    capacity: usize,
    hits: AtomicU64,
    misses: AtomicU64,
}

impl TokenCache {
    pub fn new(capacity: usize) -> Self {
        TokenCache {
            tokens: Vec::with_capacity(capacity),
            capacity,
            hits: AtomicU64::new(0),
            misses: AtomicU64::new(0),
        }
    }

    /// Lookup token by ID (O(1) average)
    pub fn lookup(&self, token_id: u64) -> Option<Token> {
        for token in &self.tokens {
            if token.id == token_id {
                self.hits.fetch_add(1, Ordering::Relaxed);
                return Some(token.clone());
            }
        }
        self.misses.fetch_add(1, Ordering::Relaxed);
        None
    }

    /// Insert token with automatic capacity management
    pub fn insert(&mut self, token: Token) -> bool {
        if self.tokens.len() >= self.capacity {
            // Remove oldest entry (first in list)
            if !self.tokens.is_empty() {
                self.tokens.remove(0);
            }
        }
        self.tokens.push(token);
        true
    }

    pub fn hit_rate(&self) -> f64 {
        let hits = self.hits.load(Ordering::Relaxed);
        let misses = self.misses.load(Ordering::Relaxed);
        let total = hits + misses;
        if total == 0 { 0.0 } else { hits as f64 / total as f64 }
    }

    pub fn stats(&self) -> (u64, u64, f64) {
        let hits = self.hits.load(Ordering::Relaxed);
        let misses = self.misses.load(Ordering::Relaxed);
        let total = hits + misses;
        let rate = if total == 0 { 0.0 } else { hits as f64 / total as f64 };
        (hits, misses, rate)
    }

    pub fn clear(&mut self) {
        self.tokens.clear();
    }

    pub fn len(&self) -> usize {
        self.tokens.len()
    }

    pub fn is_empty(&self) -> bool {
        self.tokens.is_empty()
    }
}

/// Variable: Represents a defined variable in compilation
#[derive(Debug, Clone)]
pub struct Variable {
    pub name: String,
    pub var_type: String,
    pub scope: u32,
    pub value: Option<String>,
}

/// Function: Represents a defined function in compilation
#[derive(Debug, Clone)]
pub struct Function {
    pub name: String,
    pub params: Vec<(String, String)>, // (name, type)
    pub return_type: String,
    pub scope: u32,
}

/// SharedState: Thread-safe shared compilation state
/// All 4 workers can read/write to these shared structures
pub struct SharedState {
    pub token_cache: Arc<Mutex<TokenCache>>,
    pub variables: Arc<Mutex<Vec<Variable>>>,
    pub functions: Arc<Mutex<Vec<Function>>>,
    pub errors: Arc<Mutex<Vec<String>>>,
    total_tokens: AtomicU64,
    total_time_ns: AtomicU64,
}

impl SharedState {
    pub fn new(cache_capacity: usize) -> Self {
        SharedState {
            token_cache: Arc::new(Mutex::new(TokenCache::new(cache_capacity))),
            variables: Arc::new(Mutex::new(Vec::new())),
            functions: Arc::new(Mutex::new(Vec::new())),
            errors: Arc::new(Mutex::new(Vec::new())),
            total_tokens: AtomicU64::new(0),
            total_time_ns: AtomicU64::new(0),
        }
    }

    /// Add variable to shared state
    pub fn add_variable(&self, var: Variable) -> Result<(), String> {
        match self.variables.lock() {
            Ok(mut vars) => {
                vars.push(var);
                Ok(())
            }
            Err(e) => Err(format!("Failed to lock variables: {}", e)),
        }
    }

    /// Lookup variable by name
    pub fn lookup_variable(&self, name: &str) -> Option<Variable> {
        match self.variables.lock() {
            Ok(vars) => {
                for var in vars.iter() {
                    if var.name == name {
                        return Some(var.clone());
                    }
                }
                None
            }
            Err(_) => None,
        }
    }

    /// Add function to shared state
    pub fn add_function(&self, func: Function) -> Result<(), String> {
        match self.functions.lock() {
            Ok(mut funcs) => {
                funcs.push(func);
                Ok(())
            }
            Err(e) => Err(format!("Failed to lock functions: {}", e)),
        }
    }

    /// Lookup function by name
    pub fn lookup_function(&self, name: &str) -> Option<Function> {
        match self.functions.lock() {
            Ok(funcs) => {
                for func in funcs.iter() {
                    if func.name == name {
                        return Some(func.clone());
                    }
                }
                None
            }
            Err(_) => None,
        }
    }

    /// Record error
    pub fn record_error(&self, error: String) {
        if let Ok(mut errs) = self.errors.lock() {
            errs.push(error);
        }
    }

    /// Get all variables
    pub fn get_variables(&self) -> Vec<Variable> {
        match self.variables.lock() {
            Ok(vars) => vars.clone(),
            Err(_) => Vec::new(),
        }
    }

    /// Get all functions
    pub fn get_functions(&self) -> Vec<Function> {
        match self.functions.lock() {
            Ok(funcs) => funcs.clone(),
            Err(_) => Vec::new(),
        }
    }

    /// Get all errors
    pub fn get_errors(&self) -> Vec<String> {
        match self.errors.lock() {
            Ok(errs) => errs.clone(),
            Err(_) => Vec::new(),
        }
    }

    /// Update total metrics
    pub fn update_metrics(&self, tokens: u64, time_ns: u64) {
        self.total_tokens.fetch_add(tokens, Ordering::Relaxed);
        self.total_time_ns.fetch_add(time_ns, Ordering::Relaxed);
    }

    /// Get metrics
    pub fn get_metrics(&self) -> (u64, u64) {
        (
            self.total_tokens.load(Ordering::Relaxed),
            self.total_time_ns.load(Ordering::Relaxed),
        )
    }

    /// Get token cache hit rate
    pub fn token_cache_hit_rate(&self) -> f64 {
        match self.token_cache.lock() {
            Ok(cache) => cache.hit_rate(),
            Err(_) => 0.0,
        }
    }

    pub fn clear(&self) {
        if let Ok(mut cache) = self.token_cache.lock() {
            cache.clear();
        }
        if let Ok(mut vars) = self.variables.lock() {
            vars.clear();
        }
        if let Ok(mut funcs) = self.functions.lock() {
            funcs.clear();
        }
        if let Ok(mut errs) = self.errors.lock() {
            errs.clear();
        }
    }
}

/// WorkItem: Unit of work for parallel compilation
#[derive(Debug, Clone)]
pub struct WorkItem {
    pub id: u64,
    pub source_code: String,
    pub worker_id: u32,
    pub status: WorkStatus,
}

#[derive(Debug, Clone, PartialEq)]
pub enum WorkStatus {
    Pending,
    InProgress,
    Completed,
    Failed(String),
}

impl WorkItem {
    pub fn new(id: u64, source_code: String) -> Self {
        WorkItem {
            id,
            source_code,
            worker_id: 0,
            status: WorkStatus::Pending,
        }
    }

    pub fn start(&mut self, worker_id: u32) {
        self.worker_id = worker_id;
        self.status = WorkStatus::InProgress;
    }

    pub fn complete(&mut self) {
        self.status = WorkStatus::Completed;
    }

    pub fn fail(&mut self, reason: String) {
        self.status = WorkStatus::Failed(reason);
    }

    pub fn is_pending(&self) -> bool {
        self.status == WorkStatus::Pending
    }

    pub fn is_in_progress(&self) -> bool {
        self.status == WorkStatus::InProgress
    }

    pub fn is_completed(&self) -> bool {
        self.status == WorkStatus::Completed
    }

    pub fn is_failed(&self) -> bool {
        matches!(self.status, WorkStatus::Failed(_))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_token_creation() {
        let token = Token::new(1, 0, "let".to_string(), 1, 0);
        assert_eq!(token.id, 1);
        assert_eq!(token.token_type, 0);
        assert_eq!(token.value, "let");
    }

    #[test]
    fn test_token_cache_insert_lookup() {
        let mut cache = TokenCache::new(10);
        let token = Token::new(1, 0, "fn".to_string(), 1, 0);
        cache.insert(token.clone());
        assert_eq!(cache.lookup(1), Some(token));
    }

    #[test]
    fn test_token_cache_hit_rate() {
        let mut cache = TokenCache::new(10);
        let token = Token::new(1, 0, "let".to_string(), 1, 0);
        cache.insert(token);
        cache.lookup(1); // hit
        cache.lookup(2); // miss
        let rate = cache.hit_rate();
        assert!(rate > 0.4 && rate < 0.6);
    }

    #[test]
    fn test_shared_state_add_variable() {
        let state = SharedState::new(10);
        let var = Variable {
            name: "x".to_string(),
            var_type: "i32".to_string(),
            scope: 0,
            value: Some("42".to_string()),
        };
        assert!(state.add_variable(var).is_ok());
    }

    #[test]
    fn test_shared_state_lookup_variable() {
        let state = SharedState::new(10);
        let var = Variable {
            name: "x".to_string(),
            var_type: "i32".to_string(),
            scope: 0,
            value: Some("42".to_string()),
        };
        state.add_variable(var.clone()).unwrap();
        assert_eq!(state.lookup_variable("x"), Some(var));
    }

    #[test]
    fn test_shared_state_add_function() {
        let state = SharedState::new(10);
        let func = Function {
            name: "add".to_string(),
            params: vec![("a".to_string(), "i32".to_string())],
            return_type: "i32".to_string(),
            scope: 0,
        };
        assert!(state.add_function(func).is_ok());
    }

    #[test]
    fn test_work_item_lifecycle() {
        let mut work = WorkItem::new(1, "let x = 5;".to_string());
        assert!(work.is_pending());

        work.start(0);
        assert!(work.is_in_progress());

        work.complete();
        assert!(work.is_completed());
    }

    #[test]
    fn test_work_item_failure() {
        let mut work = WorkItem::new(1, "let x = ;".to_string());
        work.fail("Syntax error".to_string());
        assert!(work.is_failed());
    }
}

