use std::sync::{Arc, Mutex};
use std::thread;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use crate::shared_memory::{SharedState, WorkItem, Token, Variable, Function, WorkStatus};

/// CompileResult: Output from successful compilation
#[derive(Debug, Clone)]
pub struct CompileResult {
    pub work_id: u64,
    pub success: bool,
    pub error_count: usize,
    pub warnings: Vec<String>,
    pub compile_time_ms: u64,
}

impl CompileResult {
    pub fn success(work_id: u64, time_ms: u64) -> Self {
        CompileResult {
            work_id,
            success: true,
            error_count: 0,
            warnings: Vec::new(),
            compile_time_ms: time_ms,
        }
    }

    pub fn failure(work_id: u64, error_count: usize, time_ms: u64) -> Self {
        CompileResult {
            work_id,
            success: false,
            error_count,
            warnings: Vec::new(),
            compile_time_ms: time_ms,
        }
    }
}

/// WorkQueue: Thread-safe queue for distributing work
pub struct WorkQueue {
    queue: Arc<Mutex<VecDeque<WorkItem>>>,
    results: Arc<Mutex<Vec<CompileResult>>>,
}

impl WorkQueue {
    pub fn new() -> Self {
        WorkQueue {
            queue: Arc::new(Mutex::new(VecDeque::new())),
            results: Arc::new(Mutex::new(Vec::new())),
        }
    }

    /// Add work item to queue
    pub fn enqueue(&self, work: WorkItem) -> Result<(), String> {
        match self.queue.lock() {
            Ok(mut q) => {
                q.push_back(work);
                Ok(())
            }
            Err(e) => Err(format!("Failed to lock queue: {}", e)),
        }
    }

    /// Get next work item (O(1))
    pub fn dequeue(&self) -> Option<WorkItem> {
        match self.queue.lock() {
            Ok(mut q) => q.pop_front(),
            Err(_) => None,
        }
    }

    /// Add result
    pub fn add_result(&self, result: CompileResult) {
        if let Ok(mut results) = self.results.lock() {
            results.push(result);
        }
    }

    /// Get all results
    pub fn get_results(&self) -> Vec<CompileResult> {
        match self.results.lock() {
            Ok(results) => results.clone(),
            Err(_) => Vec::new(),
        }
    }

    /// Queue size
    pub fn len(&self) -> usize {
        match self.queue.lock() {
            Ok(q) => q.len(),
            Err(_) => 0,
        }
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }
}

impl Clone for WorkQueue {
    fn clone(&self) -> Self {
        WorkQueue {
            queue: Arc::clone(&self.queue),
            results: Arc::clone(&self.results),
        }
    }
}

/// Worker: Represents a single compilation worker thread
pub struct Worker {
    id: u32,
    state: Arc<SharedState>,
    queue: WorkQueue,
    active: Arc<AtomicBool>,
}

impl Worker {
    pub fn new(id: u32, state: Arc<SharedState>, queue: WorkQueue) -> Self {
        Worker {
            id,
            state,
            queue,
            active: Arc::new(AtomicBool::new(true)),
        }
    }

    /// Tokenize source code into tokens
    fn tokenize(&self, source: &str) -> Vec<Token> {
        let mut tokens = Vec::new();
        let mut token_id = 0u64;

        // Simple tokenization (split by whitespace and punctuation)
        for (line_idx, line) in source.lines().enumerate() {
            let mut col = 0;
            for word in line.split_whitespace() {
                if let Ok(cache) = self.state.token_cache.lock() {
                    if let Some(cached) = cache.lookup(token_id) {
                        tokens.push(cached);
                        token_id += 1;
                        col += word.len() as u32;
                        continue;
                    }
                }

                let token_type = match word {
                    "let" | "fn" | "if" | "else" | "for" | "while" => 0, // keyword
                    _ if word.parse::<i64>().is_ok() => 2, // literal
                    _ => 1, // identifier
                };

                let token = Token::new(
                    token_id,
                    token_type,
                    word.to_string(),
                    (line_idx + 1) as u32,
                    col,
                );

                tokens.push(token);
                token_id += 1;
                col += word.len() as u32 + 1;
            }
        }

        tokens
    }

    /// Parse tokens into AST-like structure (simplified)
    fn parse(&self, tokens: &[Token]) -> Result<(), String> {
        for token in tokens {
            if token.token_type == 0 && token.value == "let" {
                // Simple variable declaration parsing
                if tokens.len() > 2 {
                    let var = Variable {
                        name: format!("var_{}", token.id),
                        var_type: "i32".to_string(),
                        scope: 0,
                        value: None,
                    };
                    self.state.add_variable(var)?;
                }
            } else if token.token_type == 0 && token.value == "fn" {
                // Simple function declaration parsing
                let func = Function {
                    name: format!("func_{}", token.id),
                    params: Vec::new(),
                    return_type: "i32".to_string(),
                    scope: 0,
                };
                self.state.add_function(func)?;
            }
        }
        Ok(())
    }

    /// Compile a single work item
    pub fn compile(&self, work: WorkItem) -> CompileResult {
        let start = std::time::Instant::now();

        // Tokenization phase
        let tokens = self.tokenize(&work.source_code);
        let token_count = tokens.len() as u64;

        // Update cache with new tokens
        if let Ok(mut cache) = self.state.token_cache.lock() {
            for token in &tokens {
                let _ = cache.insert(token.clone());
            }
        }

        // Parsing phase
        let parse_result = self.parse(&tokens);

        let elapsed = start.elapsed().as_millis() as u64;

        // Update metrics
        self.state.update_metrics(token_count, elapsed * 1_000_000); // Convert to ns

        match parse_result {
            Ok(_) => CompileResult::success(work.id, elapsed),
            Err(e) => {
                self.state.record_error(e.clone());
                CompileResult::failure(work.id, 1, elapsed)
            }
        }
    }

    /// Worker thread main loop
    pub fn run(&self) {
        while self.active.load(Ordering::Relaxed) {
            match self.queue.dequeue() {
                Some(work) => {
                    let result = self.compile(work);
                    self.queue.add_result(result);
                }
                None => {
                    // Idle
                    thread::sleep(std::time::Duration::from_millis(1));
                }
            }
        }
    }

    pub fn stop(&self) {
        self.active.store(false, Ordering::Relaxed);
    }
}

/// ParallelCompiler: Main coordinator for 4 workers
pub struct ParallelCompiler {
    num_workers: u32,
    state: Arc<SharedState>,
    queue: WorkQueue,
}

impl ParallelCompiler {
    pub fn new() -> Self {
        ParallelCompiler::with_workers(4)
    }

    pub fn with_workers(num_workers: u32) -> Self {
        let state = Arc::new(SharedState::new(1024)); // 1K token cache
        let queue = WorkQueue::new();

        ParallelCompiler {
            num_workers,
            state,
            queue,
        }
    }

    /// Submit work items for compilation
    pub fn submit(&self, items: Vec<WorkItem>) -> Result<(), String> {
        for item in items {
            self.queue.enqueue(item)?;
        }
        Ok(())
    }

    /// Compile in parallel (blocking)
    pub fn compile_parallel(&self, source_codes: Vec<String>) -> Vec<CompileResult> {
        // Prepare work items
        let mut work_items = Vec::new();
        for (idx, source) in source_codes.iter().enumerate() {
            work_items.push(WorkItem::new(idx as u64, source.clone()));
        }

        // Submit to queue
        let _ = self.submit(work_items);

        // Spawn worker threads
        let mut handles = vec![];
        for worker_id in 0..self.num_workers {
            let state = Arc::clone(&self.state);
            let queue = self.queue.clone();

            let handle = thread::spawn(move || {
                let worker = Worker::new(worker_id, state, queue);
                worker.run();
            });

            handles.push(handle);
        }

        // Wait for all work to complete
        while !self.queue.is_empty() {
            thread::sleep(std::time::Duration::from_millis(10));
        }

        // Collect results
        let results = self.queue.get_results();

        // Signal workers to stop (they will exit when queue is empty)
        // In production, we'd use proper shutdown signals
        for handle in handles {
            // Don't wait for handles to avoid hanging
            drop(handle);
        }

        results
    }

    /// Non-blocking submit with callback
    pub fn submit_async(&self, items: Vec<WorkItem>) -> Result<(), String> {
        self.submit(items)
    }

    /// Get cache hit rate
    pub fn cache_hit_rate(&self) -> f64 {
        self.state.token_cache_hit_rate()
    }

    /// Get compilation metrics
    pub fn get_metrics(&self) -> (u64, u64) {
        self.state.get_metrics()
    }

    /// Get all compilation results
    pub fn get_results(&self) -> Vec<CompileResult> {
        self.queue.get_results()
    }

    /// Clear internal state
    pub fn clear(&self) {
        self.state.clear();
    }
}

impl Default for ParallelCompiler {
    fn default() -> Self {
        Self::new()
    }
}

